package com.topitup.retailer.activity;
import android.content.Intent;import android.os.Bundle;import android.view.animation.AccelerateDecelerateInterpolator;import com.topitup.retailer.R;import com.topitup.retailer.common.ImmersiveActivity;import com.topitup.retailer.ui.login.LoginActivity;
public class SplashActivity extends ImmersiveActivity { @Override protected void onCreate(Bundle state){super.onCreate(state);setContentView(R.layout.activity_splash);android.view.View logo=findViewById(R.id.logo);logo.setScaleX(.82f);logo.setScaleY(.82f);logo.animate().alpha(1f).scaleX(1f).scaleY(1f).setDuration(900).setInterpolator(new AccelerateDecelerateInterpolator()).withEndAction(()->{startActivity(new Intent(this, LoginActivity.class));overridePendingTransition(android.R.anim.fade_in,android.R.anim.fade_out);finish();}).start();} }
